import React, { createContext, useState, useEffect } from 'react';
import { db } from '../services/firebase';
import { ref, onValue, update, get } from 'firebase/database';

export const ProductsContext = createContext();

export const ProductsProvider = ({ children }) => {
  const [products, setProducts] = useState([]);
  const [packages, setPackages] = useState([]);
  const [ribbons, setRibbons] = useState([]);
  const [promo, setPromo] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Подписка на товары
    const productsRef = ref(db, 'products');
    const unsubscribeProducts = onValue(productsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const productsArray = Object.keys(data).map(key => ({
          id: key,
          views: 0,
          ...data[key]
        }));
        setProducts(productsArray);
      } else {
        setProducts([]);
      }
    });

    // Подписка на упаковки
    const packagesRef = ref(db, 'packages');
    const unsubscribePackages = onValue(packagesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const packagesArray = Object.keys(data).map(key => ({
          id: key,
          ...data[key]
        }));
        setPackages(packagesArray);
      } else {
        setPackages([]);
      }
    });

    // Подписка на ленты
    const ribbonsRef = ref(db, 'ribbons');
    const unsubscribeRibbons = onValue(ribbonsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const ribbonsArray = Object.keys(data).map(key => ({
          id: key,
          ...data[key]
        }));
        setRibbons(ribbonsArray);
      } else {
        setRibbons([]);
      }
    });

    // Подписка на данные акции
    const promoRef = ref(db, 'promo');
    const unsubscribePromo = onValue(promoRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setPromo(data);
      } else {
        setPromo({
          bannerText: 'Скидка 20% на первый заказ!',
          bannerEnabled: true,
          promoEndDate: Date.now() + 7 * 24 * 60 * 60 * 1000,
          firstOrderDiscount: 20
        });
      }
      setLoading(false);
    });

    return () => {
      unsubscribeProducts();
      unsubscribePackages();
      unsubscribeRibbons();
      unsubscribePromo();
    };
  }, []);

  const updatePromo = async (newPromo) => {
    await update(ref(db, 'promo'), newPromo);
  };

  const incrementViews = async (productId) => {
    const productRef = ref(db, `products/${productId}`);
    const snapshot = await get(productRef);
    const currentViews = snapshot.val()?.views || 0;
    await update(productRef, { views: currentViews + 1 });
  };

  return (
    <ProductsContext.Provider value={{
      products,
      packages,
      ribbons,
      promo,
      loading,
      updatePromo,
      incrementViews
    }}>
      {children}
    </ProductsContext.Provider>
  );
};