import { BrowserRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { useContext, lazy, Suspense } from 'react';
import { Toaster } from 'react-hot-toast';
import { CartContext } from './context/CartContext';
import { AuthContext } from './context/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import Loader from './components/Loader';
import { FiShoppingCart, FiPenTool } from 'react-icons/fi';
import './App.css';

// Ленивая загрузка страниц
const Home = lazy(() => import('./pages/Home'));
const Cart = lazy(() => import('./pages/Cart'));
const Login = lazy(() => import('./pages/Login'));
const Admin = lazy(() => import('./pages/Admin'));
const BouquetBuilder = lazy(() => import('./pages/BouquetBuilder'));

// Компонент навбара для обычных страниц
const NavBar = () => {
  const { cart } = useContext(CartContext);
  const { user } = useContext(AuthContext);
  const location = useLocation();
  
  if (location.pathname === '/admin') {
    return null;
  }
  
  const cartCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <nav className="navbar">
      <Link to="/" className="logo">🌸 Flower Shop</Link>
      <div className="nav-links">
        <Link to="/">Главная</Link>
        <Link to="/builder" className="builder-link">
          <FiPenTool /> Собрать букет
        </Link>
        <Link to="/cart" className="cart-link">
          Корзина 
          {cartCount > 0 && <span className="cart-count">{cartCount}</span>}
          <FiShoppingCart />
        </Link>
        {user ? (
          <Link to="/admin">Админка</Link>
        ) : (
          <Link to="/login">Вход</Link>
        )}
      </div>
    </nav>
  );
};

function App() {
  return (
    <BrowserRouter>
      <Toaster 
        position="top-center"
        toastOptions={{
          duration: 3000,
          style: {
            background: '#fff',
            color: '#4a4a4a',
            boxShadow: '0 5px 15px rgba(255,182,193,0.3)',
            borderRadius: '10px',
            padding: '12px 20px',
            fontSize: '14px',
            fontWeight: '500',
          },
        }}
      />
      
      <NavBar />

      <Suspense fallback={<Loader />}>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/builder" element={<BouquetBuilder />} />
          <Route path="/cart" element={<Cart />} />
          <Route path="/login" element={<Login />} />
          <Route 
            path="/admin" 
            element={
              <ProtectedRoute>
                <Admin />
              </ProtectedRoute>
            } 
          />
        </Routes>
      </Suspense>
    </BrowserRouter>
  );
}

export default App;